        $invoiceId=$auth['invoices']?'i.id':'NULL';$invoiceNumber=$auth['invoices']?"COALESCE(d.formatted_number,'')":"''";$paid=$auth['invoices']?'CASE WHEN i.id IS NULL THEN 0 WHEN i.status=2 THEN 1 ELSE 0 END':'NULL';
