        $sql='SELECT COALESCE(SUM(q.total_cents),0) all_cents,COALESCE(SUM(CASE WHEN q.billable=1 THEN q.total_cents ELSE 0 END),0) billable_cents,COALESCE(SUM(CASE WHEN q.billable=0 THEN q.total_cents ELSE 0 END),0) non_billable_cents,COALESCE(SUM(CASE WHEN q.billable=1 AND q.unbilled=1 THEN q.total_cents ELSE 0 END),0) unbilled_cents,COALESCE(SUM(CASE WHEN q.billable=1 AND q.paid=1 THEN q.total_cents ELSE 0 END),0) billed_cents,COUNT(CASE WHEN q.billable IS NULL THEN 1 END) undeclared_count,COUNT(CASE WHEN q.billable=1 AND q.unbilled IS NULL THEN 1 END) pending_count FROM ('.$source['sql'].') q WHERE '.implode(' AND ',$where);$row=$this->rows($sql,$args)[0];$totals=[];foreach(['all','billable','non_billable','unbilled','billed']as$key)$totals[$key]=['cents'=>$key==='billed'&&!$auth['invoices']?null:(string)$row[$key.'_cents'],'total'=>$key==='billed'&&!$auth['invoices']?null:self::formatCents($row[$key.'_cents'],$currency)];
        $yearSql='SELECT DISTINCT q.year FROM ('.$source['sql'].') q ORDER BY q.year DESC';$available=$this->rows($yearSql,$source['params']);if(!in_array(gmdate('Y'),array_column($available,'year'),true))array_unshift($available,['year'=>gmdate('Y')]);
